<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
final class Promotions {
    public static function decimal($v,int $max=100000000):int {Config::require(is_string($v)&&preg_match('/^([0-9]{1,7})(?:[.,]([0-9]{1,2}))?$/D',trim($v),$m),'invalid_decimal');return Config::integer((int)$m[1]*100+(int)str_pad($m[2]??'',2,'0'),0,$max);}
    public static function rules(array $r):array {$scope=$r['scope']??'all';$audience=$r['audience']??'all';Config::require(in_array($scope,array('all','extras'),true)&&in_array($audience,array('all','subscribers'),true),'invalid_promotion_scope');$ids=$r['addon_ids']??array();Config::require(is_array($ids)&&count($ids)<=15,'invalid_promotion_extras');foreach($ids as $id)Config::require(is_string($id)&&preg_match('/^[a-z0-9_-]{1,50}$/D',$id),'invalid_promotion_extras');return array('scope'=>$scope,'audience'=>$audience,'addon_ids'=>array_values(array_unique($ids)));}
    public static function get(int $coupon):array {global $wpdb;return json_decode((string)$wpdb->get_var($wpdb->prepare('SELECT payload FROM '.DB::table('coupon_rules').' WHERE coupon_id=%d',$coupon)),true)?:array('scope'=>'all','audience'=>'all','addon_ids'=>array());}
    public static function eligible(array $coupon,int $base,string $email,array $selection):int {
        global $wpdb;$rule=self::get((int)$coupon['id']);$campaign=$wpdb->get_row($wpdb->prepare('SELECT enabled FROM '.DB::table('campaigns').' WHERE coupon_id=%d',$coupon['id']),ARRAY_A);Config::require(!$campaign||(bool)$campaign['enabled'],'coupon_campaign_paused');
        if($rule['audience']==='subscribers'){$c=DB::row('contacts','email',Config::email($email));Config::require($c&&$c['state']==='confirmed','coupon_newsletter_required');}
        if($rule['scope']==='all')return $base;$eligible=0;foreach($selection['addons']??array()as $a)if(!$rule['addon_ids']||in_array($a['id'],$rule['addon_ids'],true))$eligible+=$a['amount_cents'];Config::require($eligible>0,'coupon_no_eligible_extras');return $eligible;
    }
    public static function settings(array $d):void {
        Config::require(current_user_can('manage_options'),'permission_denied');foreach(array('loyalty','welcome')as $kind){$enabled=!empty($d[$kind.'_enabled']);$key='vpm_booking_'.$kind.'_enabled';if($enabled&&!get_option($key,false))update_option('vpm_booking_'.$kind.'_starts',time(),false);update_option($key,$enabled,false);update_option('vpm_booking_'.$kind.'_bps',isset($d[$kind.'_percent'])?Config::integer(self::decimal($d[$kind.'_percent'],10000),1,10000):Commerce::number($d[$kind.'_bps']??500,1,10000),false);}Operations::audit('promotions.settings_saved','campaign',0);
    }
    public static function create(array $d):array {
        Config::require(current_user_can('manage_options'),'permission_denied');$name=sanitize_text_field($d['name']??'');Config::require($name!==''&&strlen($name)<=180,'invalid_campaign_name');$rule=self::rules($d);$input=array('code'=>strtoupper(trim((string)($d['code']??''))),'kind'=>$d['kind']??'percent','value'=>!empty($d['ui_units'])?Config::integer(self::decimal((string)($d['value']??''),($d['kind']??'percent')==='percent'?10000:100000000),1):Commerce::number($d['value']??0,1),'starts_at'=>Commerce::number($d['starts_at']??0,0,PHP_INT_MAX),'ends_at'=>Commerce::number($d['ends_at']??0,1,PHP_INT_MAX),'budget_cents'=>Commerce::number($d['budget_cents']??0,1),'max_uses'=>Commerce::number($d['max_uses']??1,1,1000000),'max_per_customer'=>Commerce::number($d['max_per_customer']??1,1,1000000),'promotion_rules'=>$rule);
        return DB::tx(function()use($d,$name,$input){$coupon=Core::coupon($input);$id=DB::insert('campaigns',array('coupon_id'=>$coupon['id'],'name'=>$name,'enabled'=>empty($d['enabled'])?0:1,'notify'=>empty($d['notify_subscribers'])?0:1));Operations::audit('promotion.created','campaign',$id);return array('campaign_id'=>$id,'coupon'=>$coupon);});
    }
    public static function automatic(array $partner,int $base,string $email,array $selection):?array {
        global $wpdb;$items=$wpdb->get_results('SELECT c.* FROM '.DB::table('coupons').' c INNER JOIN '.DB::table('campaigns').' p ON p.coupon_id=c.id WHERE p.enabled=1 ORDER BY p.id LIMIT 100',ARRAY_A);$best=null;$amount=0;foreach($items as $c){if(self::get((int)$c['id'])['audience']!=='all')continue;try{$discount=Vouchers::evaluate($c,$partner,$base,$email,null,$selection);Finance::quote($base,(int)$partner['commission_bps'],$discount);if($discount>$amount){$best=$c;$amount=$discount;}}catch(\Throwable $e){continue;}}return $best;
    }
    public static function welcome(int $contact):?array {
        if(!get_option('vpm_booking_welcome_enabled',false))return null;
        return DB::tx(function()use($contact){global $wpdb;$c=DB::row('contacts','id',$contact,true);if(!$c||$c['state']!=='confirmed'||(int)$c['confirmed_at']<(int)get_option('vpm_booking_welcome_starts',PHP_INT_MAX))return null;if($wpdb->get_var($wpdb->prepare('SELECT coupon_id FROM '.DB::table('rewards')." WHERE contact_id=%d AND kind='welcome'",$contact)))return null;
            $issued=time();$expires=(new \DateTimeImmutable('@'.$issued))->add(new \DateInterval('P2Y'))->getTimestamp();$bps=(int)get_option('vpm_booking_welcome_bps',500);$coupon=Core::coupon(array('code'=>'WELCOME-'.strtoupper(bin2hex(random_bytes(10))),'kind'=>'percent','value'=>$bps,'starts_at'=>$issued,'ends_at'=>$expires,'max_uses'=>1,'max_per_customer'=>1,'budget_cents'=>5000000,'customer_hash'=>hash_hmac('sha256',$c['email'],wp_salt('auth')),'promotion_rules'=>array('audience'=>'all')));DB::insert('rewards',array('contact_id'=>$contact,'kind'=>'welcome','coupon_id'=>$coupon['id']));Automation::event('welcome:'.$contact,'welcome.coupon_issued','marketing',array('recipient'=>$c['email'],'coupon_code'=>$coupon['code'],'discount_bps'=>$bps,'expires_at'=>$expires,'consent_revision'=>(int)$c['revision'],'consent_version'=>$c['consent_version'],'unsubscribe_url'=>Consent::unsubscribe_url($c)),$contact);Operations::audit('welcome.coupon_issued','coupon',(int)$coupon['id']);return $coupon;
        });
    }
    public static function run():void {
        global $wpdb;if(get_option('vpm_booking_welcome_enabled',false)){$cursor=(int)get_option('vpm_booking_welcome_cursor',0);$ids=$wpdb->get_col($wpdb->prepare('SELECT id FROM '.DB::table('contacts')." WHERE state='confirmed' AND id>%d ORDER BY id LIMIT 20",$cursor));foreach($ids as $id){self::welcome((int)$id);$cursor=(int)$id;}update_option('vpm_booking_welcome_cursor',count($ids)<20?0:$cursor,false);}
        $campaigns=$wpdb->get_results($wpdb->prepare('SELECT p.*,c.code,c.kind,c.value,c.starts_at,c.ends_at FROM '.DB::table('campaigns').' p INNER JOIN '.DB::table('coupons').' c ON c.id=p.coupon_id WHERE p.enabled=1 AND p.notify=1 AND c.starts_at<=%d AND c.ends_at>%d ORDER BY p.id LIMIT 20',time(),time()),ARRAY_A);
        foreach($campaigns as $campaign){$cursor=(int)$campaign['cursor_id'];$contacts=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.DB::table('contacts')." WHERE state='confirmed' AND id>%d ORDER BY id LIMIT 20",$cursor),ARRAY_A);foreach($contacts as $c){Automation::event('promotion:'.$campaign['id'].':'.$c['id'],'promotion.campaign_announced','marketing',array('recipient'=>$c['email'],'campaign_id'=>(int)$campaign['id'],'campaign_name'=>$campaign['name'],'coupon_code'=>$campaign['code'],'discount_kind'=>$campaign['kind'],'discount_value'=>(int)$campaign['value'],'starts_at'=>(int)$campaign['starts_at'],'expires_at'=>(int)$campaign['ends_at'],'promotion_rules'=>self::get((int)$campaign['coupon_id']),'consent_revision'=>(int)$c['revision'],'consent_version'=>$c['consent_version'],'unsubscribe_url'=>Consent::unsubscribe_url($c)),(int)$c['id']);$cursor=(int)$c['id'];}DB::update('campaigns',array('cursor_id'=>count($contacts)<20?0:$cursor),array('id'=>$campaign['id']));}
    }
    public static function message_allowed(array $payload):bool {if(empty($payload['campaign_id']))return true;global $wpdb;$c=$wpdb->get_row($wpdb->prepare('SELECT p.enabled,c.starts_at,c.ends_at FROM '.DB::table('campaigns').' p INNER JOIN '.DB::table('coupons').' c ON c.id=p.coupon_id WHERE p.id=%d',$payload['campaign_id']),ARRAY_A);return $c&&(bool)$c['enabled']&&(int)$c['starts_at']<=time()&&(int)$c['ends_at']>time();}
}
